\label{prop:hardiman-tube-center-equivalence}
For every $x\in\mathfrak{Z}( {\cal R} )$, the construction above defines a $*$-functor
$x^\sharp:\mathsf{Tube}_{\mathrm v}( {\cal R} )\rightarrow\mathsf{Hilb}$. Moreover, the assignment
$x\mapsto x^\sharp$ extends to a unitary equivalence
\begin{equation}
    (-)^\sharp: \mathfrak{Z}( {\cal R} )^{\mathrm{op}}
    \cong \mathsf{Fun}_*\bigl(\mathsf{Tube}_{\mathrm v}( {\cal R} ),\mathsf{Hilb}\bigr),
\end{equation}
where the right-hand side is the category of $*$-functors to finite-dimensional
Hilbert spaces and natural transformations.

For all $A,B\in {\cal R} $, the anyon-insertion maps associated with the simple
objects of $\mathfrak{Z}( {\cal R} )$ assemble into a linear isomorphism
\begin{equation}\label{eq:tube-sector-decomposition}
\begin{aligned}
    \Phi_{A,B}:\mathsf{Tube}_{\mathrm v}( {\cal R} )(A,B)
    &\xrightarrow{\ \simeq\ }
    \bigoplus_{z\in\mathrm{Irr}\mathfrak{Z}( {\cal R} )}
    \mathsf{Hilb}\bigl(z^\sharp(A),z^\sharp(B)\bigr),\\
    u&\longmapsto
    \bigl(z^\sharp_{A,B}(u)\bigr)_{z}.
\end{aligned}
\end{equation}
For $A=B$, this is an isomorphism of finite-dimensional $C^*$-algebras.

For every $x=(X,\gamma_{X,-})\in\mathrm{Irr}\mathfrak{Z}( {\cal R} )$ and
$T\in {\cal R} (A\otimes B, B \otimes A)$,
\begin{equation*}
    Z_{\kappa(x)}^{\mathrm h}\!\left(T
    \right)
    =\frac{1}{D_ {\cal R} ^2}
      \sum_{y\in\mathrm{Irr}\mathfrak{Z}( {\cal R} )}S_{xy}Z_y^{\mathrm v}(T).
\end{equation*}
Graphically, this reads
\begin{multline}
\frac{1}{D_ {\cal R} ^2}\sum_{y\in\mathrm{Irr}\mathfrak{Z}( {\cal R} )}\frac{S_{xy}}{d_Y}\\
\times \sum_{I}
\raisebox{-25.61763pt}{\includegraphics{figures/tikz/modular-s-y-loop-expansion.pdf}} \\
= \frac{1}{d_X}\sum_J
\raisebox{-30.6559pt}{\includegraphics{figures/tikz/modular-s-x-projector.pdf}}.
\end{multline}

\begin{multline}
\frac{1}{D_ {\cal R} ^2}\sum_{y}\frac{S_{xy}}{d_Y}\sum_{I}
\raisebox{-28.85274pt}{\includegraphics{figures/tikz/modular-s-y-projector.pdf}} \\
    = \frac{1}{d_X}\sum_J
\raisebox{-28.85274pt}{\includegraphics{figures/tikz/modular-s-x-projector-resolved.pdf}}.
\end{multline}
holds for all $A,B\in {\cal R} $ and
$x=(X,\gamma_{X,-})\in\mathrm{Irr}\mathfrak{Z}( {\cal R} )$.

The tensor unit $\mathbb{1}\boxtimes\mathbb{1}$ occurs in $A$ with multiplicity
    one, so $A$ is connected. Separability follows from
    Proposition~\ref{prop:diagonal-algebra}.
    For commutativity, fix $i,j,k\in\mathrm{Irr}( {\cal C} )$ and define the
    braiding coefficients in the chosen orthonormal fusion bases by
    \[
        \raisebox{-29pt}{\includegraphics{figures/tikz/qsystem-r-definition-crossed-beta.pdf}}
        =\sum_{\alpha}
        R^{ij}_{k,\alpha\beta}
        \raisebox{-22pt}{\includegraphics{figures/tikz/qsystem-r-definition-plain-alpha.pdf}}.
    \]
    On these summands, the braiding of $A$ is
    $\beta_{i^*,j^*}^{-1}\boxtimes\beta_{i,j}$.
    The inverse braiding and braiding act on the two factors as
    \[
    \begin{aligned}
        &\left(q^{j\otimes i}_{k,\alpha}\right)^*
        \circ\beta_{i^*,j^*}^{-1}=\sum_{\gamma=1}^{N^{ij}_k}
        (R^{-1})^{ij}_{k,\gamma\alpha}
        \left(q^{i\otimes j}_{k,\gamma}\right)^*,\\[3pt]
        &\left(q^{j\otimes i}_{k,\alpha}\right)^\dagger
        \circ\beta_{i,j}=\sum_{\beta=1}^{N^{ij}_k}
        R^{ij}_{k,\alpha\beta}
        \left(q^{i\otimes j}_{k,\beta}\right)^\dagger.
    \end{aligned}
    \]
    The corresponding graphical calculation is
    \begin{align*}
        &\frac{1}{D}\sqrt{\frac{d_id_j}{d_k}}
        \sum_{\alpha=1}^{N^{ji}_k}
        \raisebox{-29pt}{\includegraphics{figures/tikz/qsystem-braid-dual-crossed-alpha.pdf}}
        \boxtimes
        \raisebox{-29pt}{\includegraphics{figures/tikz/qsystem-braid-adjoint-crossed-alpha.pdf}}
        \\
        &\quad=\frac{1}{D}\sqrt{\frac{d_id_j}{d_k}}
        \sum_{\gamma,\beta}
        \Biggl[\sum_{\alpha}
        (R^{-1})^{ij}_{k,\gamma\alpha}
        R^{ij}_{k,\alpha\beta}\Biggr]\\*
        &\qquad\times
        \raisebox{-22pt}{\includegraphics{figures/tikz/qsystem-braid-dual-plain-gamma.pdf}}
        \boxtimes
        \raisebox{-22pt}{\includegraphics{figures/tikz/qsystem-braid-adjoint-plain-beta.pdf}}
        \\
        &\quad=\frac{1}{D}\sqrt{\frac{d_id_j}{d_k}}
        \sum_{\beta=1}^{N^{ij}_k}
        \raisebox{-22pt}{\includegraphics{figures/tikz/qsystem-braid-dual-plain-beta.pdf}}
        \boxtimes
        \raisebox{-22pt}{\includegraphics{figures/tikz/qsystem-braid-adjoint-plain-beta.pdf}}.
    \end{align*}
    The first diagram uses the reversed strand arrows and tensor-product
    direction of the dual factor. The coefficient in brackets reduces to
    \[
        \sum_{\alpha=1}^{N^{ji}_k}
        (R^{-1})^{ij}_{k,\gamma\alpha}
        R^{ij}_{k,\alpha\beta}
        =\delta_{\gamma\beta}.
    \]
    The remaining paired sum is the corresponding component of $m$.
    Hence $m\circ\beta_{A,A}=m$, and $A$ is condensable.

    If $ {\cal C} $ is modular, $\overline{ {\cal C} }\boxtimes {\cal C} $ is a UMTC, and
    \[
        d_A=\sum_{i\in\mathrm{Irr}( {\cal C} )}d_i^2
        =D_{ {\cal C} }^2=D_{\overline{ {\cal C} }\boxtimes {\cal C} }.
    \]
    Hence $A$ is Lagrangian.

The objects of $\mathsf{Tube}_{\mathrm v}( {\cal R} )$ are the objects of $ {\cal R} $, and its morphism
spaces are
\begin{equation*}
    \mathsf{Tube}_{\mathrm v}( {\cal R} )(A,B)
    :=\int^{X\in {\cal R} } {\cal R} (A\otimes X,X\otimes B).
\end{equation*}
Denote the universal dinatural maps by
\begin{equation*}
    \pi_X^{A,B}: {\cal R} (A\otimes X,X\otimes B)
    \longrightarrow\mathsf{Tube}_{\mathrm v}( {\cal R} )(A,B).
\end{equation*}
Vertical composition is determined by the universal property of the coends
and the commutative diagram

\begin{equation*}
\resizebox{\columnwidth}{!}{ 
\includegraphics{figures/tikz/directional-tube-trace-square.pdf} 
}
\end{equation*}

where
\begin{equation*}
    \mathrm{ct}_{\mathrm v}(f\otimes g)
    :=(\mathrm{id}_X\otimes g)\circ(f\otimes\mathrm{id}_Y).
\end{equation*}
The identity morphism of $A$ is
\begin{equation*}
    \mathrm{id}_A^{\mathrm v}:=\pi_\mathbb{1}^{A,A}(\mathrm{id}_A),
\end{equation*}
where the unitors are suppressed.  Dinaturality makes the induced composition
well defined, while monoidal coherence gives associativity and the unit laws.
As usual, we suppress all associators and unitors.

Equip the reverse category $ {\cal R} ^{\mathrm{rev}}$ with the tensor product
$A\otimes_{ {\cal R} ^{\mathrm{rev}}}B:=B\otimes_ {\cal R}  A$, and define the horizontal
tube category by
\begin{equation*}
    \mathsf{Tube}_{\mathrm h}( {\cal R} ):=\mathsf{Tube}_{\mathrm v}( {\cal R} ^{\mathrm{rev}}).
\end{equation*}
In particular,
\begin{equation*}
    \mathsf{Tube}_{\mathrm h}( {\cal R} )(X,Y)
    \simeq\int^{A\in {\cal R} } {\cal R} (A\otimes X,Y\otimes A).
\end{equation*}
Denote the corresponding universal dinatural maps by
\begin{equation*}
    \varpi_A^{X,Y}: {\cal R} (A\otimes X,Y\otimes A)
    \longrightarrow\mathsf{Tube}_{\mathrm h}( {\cal R} )(X,Y).
\end{equation*}
The horizontal composition and identities are those of
$\mathsf{Tube}_{\mathrm v}( {\cal R} ^{\mathrm{rev}})$. In particular,
\begin{equation*}
    \mathrm{id}_X^{\mathrm h}:=\varpi_\mathbb{1}^{X,X}(\mathrm{id}_X).
\end{equation*}
Thus passing from one direction to the other reverses the tensor product. It
is not merely a relabeling of objects.

For fixed $A$, the family $\Theta_{A,X}$ is dinatural in $X$ and hence
induces a unique linear map
\begin{equation*}
\begin{aligned}
    \Theta_A:\mathrm{End}_{\mathsf{Tube}_{\mathrm v}( {\cal R} )}(A)&\longrightarrow\mathsf{Torus}_{\mathrm h}( {\cal R} ),\\
    \Theta_A\pi_X^{A,A}&=\Theta_{A,X}.
\end{aligned}
\end{equation*}
The family $(\Theta_A)_{A\in\mathsf{Tube}_{\mathrm v}( {\cal R} )}$ is a cowedge for the categorical
trace of $\mathsf{Tube}_{\mathrm v}( {\cal R} )$.  Consequently the universal property of that trace
induces a unique isomorphism
\begin{equation*}
    \mathscr{S}_{\mathrm{cut}}:
    \mathsf{Torus}_{\mathrm v}( {\cal R} )\xrightarrow{\ \simeq\ }\mathsf{Torus}_{\mathrm h}( {\cal R} ),
\end{equation*}
characterized on square generators by
\begin{equation}
    \mathscr{S}_{\mathrm{cut}}
    \!\left(\iota_A^{\mathrm v}\!\left(\pi_X^{A,A}(u)\right)\right)
    =\iota_X^{\mathrm h}\!\left(\varpi_A^{X,X}(u)\right).
    \label{eq:appendix-change-of-cut}
\end{equation}
Its inverse is induced by the same construction with the two directions
interchanged.

For $f:X\to Y$ and $u:A\otimes Y\to X\otimes A$, horizontal trace
cyclicity, applied to the horizontal tube morphisms represented by $f$ with
running label $\mathbb{1}$ and by $u$ with running label $A$, gives
\begin{equation*}
    \Theta_{A,X}\bigl(u(\mathrm{id}_A\otimes f)\bigr)
    =\Theta_{A,Y}\bigl((f\otimes\mathrm{id}_A)u\bigr).
\end{equation*}
Thus $\Theta_{A,X}$ is dinatural in $X$, and the first assertion follows
from the universal property of the tube coend.

It remains only to verify the cowedge condition for $\Theta_A$.  By the
universal property of the tube coends and linearity, it suffices to use
the tube morphisms
\begin{align*}
    P&:=\pi_X^{A,B}(p)\in\mathsf{Tube}_{\mathrm v}( {\cal R} )(A,B),\\
    Q&:=\pi_Y^{B,A}(q)\in\mathsf{Tube}_{\mathrm v}( {\cal R} )(B,A),
\end{align*}
represented respectively by
\begin{align*}
    p&:A\otimes X\longrightarrow X\otimes B,\\
    q&:B\otimes Y\longrightarrow Y\otimes A.
\end{align*}
By the definition of vertical tube composition,
\begin{align*}
    Q\circ_{\mathrm v}P
    &=\pi_{X\otimes Y}^{A,A}\!\left(
        \mathrm{ct}_{\mathrm v}(p\otimes q)\right),\\
    P\circ_{\mathrm v}Q
    &=\pi_{Y\otimes X}^{B,B}\!\left(
        \mathrm{ct}_{\mathrm v}(q\otimes p)\right).
\end{align*}
By the definition of $\Theta_A$,
\begin{align*}
    \Theta_A\!\left(Q\circ_{\mathrm v}P\right)
    &=\iota_{XY}^{\mathrm h}\!\left(
        \varpi_A^{XY,XY}\!\left(\mathrm{ct}_{\mathrm v}(p\otimes q)\right)
      \right),\\
    \Theta_B\!\left(P\circ_{\mathrm v}Q\right)
    &=\iota_{YX}^{\mathrm h}\!\left(
        \varpi_B^{YX,YX}\!\left(\mathrm{ct}_{\mathrm v}(q\otimes p)\right)
      \right).
\end{align*}

Consider the canonical cyclic swap
\begin{equation*}
    \operatorname{swap}_{X,Y}
    :=\varpi_X^{YX,XY}(\mathrm{id}_{XYX})
    \in\mathsf{Tube}_{\mathrm h}( {\cal R} )(YX,XY).
\end{equation*}
Choose a right dual $X^*$.  Its inverse is
\begin{equation*}
    \operatorname{swap}_{X,Y}^{-1}
    :=\varpi_{X^*}^{XY,YX}\!\left(
        (\mathrm{id}_Y\otimes\mathrm{ev}_X^\dagger)
        \circ(\mathrm{coev}_X^\dagger\otimes\mathrm{id}_Y)
      \right).
\end{equation*}
Their cut-square representatives are
\begin{equation*}
    \includegraphics[scale=.8]{figures/tikz/directional-cyclic-swap.pdf}
\end{equation*}
The first uses $\mathrm{id}_{XYX}$, and the second uses the indicated evaluation
and coevaluation. No braiding in $ {\cal R} $ is involved.
Indeed, horizontal dinaturality together with the two snake identities gives
\begin{align*}
    \operatorname{swap}_{X,Y}^{-1}
      \circ_{\mathrm h}\operatorname{swap}_{X,Y}
    &=\mathrm{id}_{YX}^{\mathrm h},\\
    \operatorname{swap}_{X,Y}
      \circ_{\mathrm h}\operatorname{swap}_{X,Y}^{-1}
    &=\mathrm{id}_{XY}^{\mathrm h}.
\end{align*}

Apply horizontal dinaturality to
\begin{equation*}
    p:A\otimes X\longrightarrow X\otimes B
\end{equation*}
and the morphism
\begin{equation*}
    \mathrm{id}_X\otimes q\otimes\mathrm{id}_X:
    (XB)\otimes(YX)\longrightarrow(XY)\otimes(AX).
\end{equation*}
This gives the intertwining relation
\begin{multline*}
    \operatorname{swap}_{X,Y}\circ_{\mathrm h}
    \varpi_B^{YX,YX}\!\left(\mathrm{ct}_{\mathrm v}(q\otimes p)\right)\\
    =\varpi_A^{XY,XY}\!\left(\mathrm{ct}_{\mathrm v}(p\otimes q)\right)
    \circ_{\mathrm h}\operatorname{swap}_{X,Y}.
\end{multline*}
Thus the two horizontal endomorphisms are conjugate by
$\operatorname{swap}_{X,Y}$.  Since categorical trace is invariant under
conjugation,
\begin{equation*}
    \Theta_A\!\left(Q\circ_{\mathrm v}P\right)
    =\Theta_B\!\left(P\circ_{\mathrm v}Q\right).
\end{equation*}
In the cut-square picture, this equality of horizontal trace classes is
\begin{equation*}
    \includegraphics[scale=.8]{figures/tikz/directional-torus-cyclicity.pdf}
\end{equation*}
This is the cowedge condition for $(\Theta_A)_A$.  The universal property of
the vertical torus coend therefore induces the unique map
$\mathscr{S}_{\mathrm{cut}}$ with Eq.~\eqref{eq:appendix-change-of-cut}.

Interchanging the horizontal and vertical variables gives a cowedge in the
opposite direction and hence an inverse map.  Both composites are the identity
on the universal square generators, so $\mathscr{S}_{\mathrm{cut}}$ is an
isomorphism.

For every $y\in\mathrm{Irr}\mathfrak{Z}( {\cal R} )$,
\begin{equation*}
    Z_{\kappa(y)}^{\mathrm h}\circ\mathscr{S}_{\mathrm{cut}}
    =\sum_{x\in\mathrm{Irr}\mathfrak{Z}( {\cal R} )}
      \frac{S_{yx}}{D_ {\cal R} ^2}\,Z_x^{\mathrm v}.
\end{equation*}

It suffices to evaluate both sides on the sector basis.  For
$x\in\mathrm{Irr}\mathfrak{Z}( {\cal R} )$, Eq.~\eqref{eq:appendix-mixed-sector-pairing} gives the value of the
left-hand side on $e_x^{\mathrm v}$, while the right-hand side gives
\begin{equation*}
    \sum_{z\in\mathrm{Irr}\mathfrak{Z}( {\cal R} )}
      \frac{S_{yz}}{D_ {\cal R} ^2}Z_z^{\mathrm v}(e_x^{\mathrm v})
    =\frac{S_{yx}}{D_ {\cal R} ^2}.
\end{equation*}
Thus the two linear functionals agree on a basis of $\mathsf{Torus}_{\mathrm v}( {\cal R} )$.
